import { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import api from '../api/api';

export default function Confirmation() {
  const { id } = useParams();
  const [booking, setBooking] = useState(null);

  useEffect(() => {
    api.get('/bookings/my').then(({ data }) => {
      setBooking(data.find((b) => b._id === id));
    });
  }, [id]);

  if (!booking) return <p>Loading confirmation...</p>;

  return (
    <div className="confirmation-page">
      <h2>Booking confirmed</h2>
      <p>Booking ID: {booking._id}</p>
      <p>Station: {booking.station?.name}</p>
      <p>Charger: {booking.charger?.chargerCode} ({booking.charger?.type})</p>
      <p>Date: {booking.date} · {booking.startTime} - {booking.endTime}</p>
      <p>Amount paid: ₹{booking.estimatedCost}</p>
      <p>Status: {booking.status}</p>
      <Link to={`/navigate/${booking.station?._id}`}>Get directions to station</Link>
    </div>
  );
}
